CREATE TABLE [sales].[CustomerAddresses] ([AddressId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_CustomerAddresses_Id] DEFAULT NEWSEQUENTIALID(),[CustomerId] UNIQUEIDENTIFIER NOT NULL,[AddressType] NVARCHAR(30) NOT NULL,[AddressLine1] NVARCHAR(250) NOT NULL,[AddressLine2] NVARCHAR(250) NULL,[City] NVARCHAR(100) NOT NULL,[District] NVARCHAR(100) NULL,[State] NVARCHAR(100) NOT NULL,[Country] NVARCHAR(100) NOT NULL CONSTRAINT [DF_CustomerAddresses_Country] DEFAULT 'India',[PostalCode] NVARCHAR(10) NOT NULL,CONSTRAINT [PK_CustomerAddresses] PRIMARY KEY([AddressId]),CONSTRAINT [FK_CustomerAddresses_Customers] FOREIGN KEY([CustomerId]) REFERENCES [sales].[Customers]([CustomerId]) ON DELETE CASCADE,CONSTRAINT [CK_CustomerAddresses_Type] CHECK([AddressType] IN('Billing','Shipping')));
GO
CREATE INDEX [IX_CustomerAddresses_CustomerId] ON [sales].[CustomerAddresses]([CustomerId]);
